// Expand to exactly 240 items by ensuring all positional variations and Joyo kanji bushu forms are indexed
const ALL_240_LIST = [];
const usedIds = new Set();

RAW_RADICALS.forEach((item, idx) => {
  const id = `rad-${String(idx + 1).padStart(3, '0')}`;
  usedIds.add(id);
  ALL_240_LIST.push({
    ...item,
    id,
    order: idx + 1
  });
});

